# region: emit
def emit(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: render
def render(xs, floor_=6):
    return [v for v in xs if v >= floor_]

# region: intake
def intake(xs):
    d = {}
    for v in xs:
        d[v % 3] = d.get(v % 3, 0) + 1
    return {'n': len(xs) - 1, 'tally': sorted(d.items())}

# region: shape
def shape(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return shape(intake(render(emit(raw))))

